class ScenarioReader(object):
    """Module responsile for parsing scenario file"""
    def __init__(self):
        pass

    def _read_scenario_file(self, scenario_path):
        try:
            with open(scenario_path) as scenario_file:
                scenario_lst = scenario_file.readlines()
            return scenario_lst
        except IOError:
            raise ScenarioFileDoesNotExist("Can not access scenario file. Please check the path: {}".format(scenario_path))


class ScenarioFileDoesNotExist(Exception):
    """Exception which should be raised when scenario file does not exist"""
    pass
